<?php

namespace Tests\Feature\Ai;

use App\Ai\Ocr\ReceiptTextParser;
use App\Ai\Ocr\TesseractReceiptExtractor;
use App\Finance\TransactionTypeSuggester;
use Symfony\Component\Process\Process;
use Tests\TestCase;

/**
 * Real local Tesseract on a SYNTHETIC ruled-table sales invoice (generated by
 * scripts/ocr-benchmark/generate.py --table-fixture; invented names, no real data).
 * Skipped when tesseract with ara+eng isn't installed.
 */
class TableInvoiceOcrTest extends TestCase
{
    private const FIXTURE = __DIR__.'/../../fixtures/ocr/table-invoice-synthetic.png';

    protected function setUp(): void
    {
        parent::setUp();
        TesseractReceiptExtractor::flushLanguageCache();
        config(['ai.ocr.tesseract_path' => 'tesseract', 'ai.ocr.tessdata_dir' => null, 'ai.ocr.preprocess' => true, 'ai.ocr.psm' => 6, 'ai.ocr.table_pass' => true]);
        $p = new Process(['tesseract', '--list-langs']);
        try {
            $p->run();
        } catch (\Throwable) {
        }
        if (! $p->isSuccessful() || ! str_contains($p->getOutput(), 'ara') || ! extension_loaded('gd')) {
            $this->markTestSkipped('tesseract with ara+eng (and GD) not installed');
        }
    }

    public function test_table_invoice_items_total_number_date_customer_and_type(): void
    {
        $parser = new ReceiptTextParser;
        $ocr = (new TesseractReceiptExtractor($parser))->ocrPageAndLines(self::FIXTURE);
        $r = $parser->parse((string) $ocr['page'], $ocr['lines'], $ocr['table']);

        $this->assertSame([[2, 12000, 24000], [1, 4000, 4000], [1, 6000, 6000], [3, 2500, 7500]],
            array_map(fn ($i) => [$i['quantity'], $i['unit_price'], $i['total']], $r->items));
        $this->assertSame('حاسوب محمول', $r->items[0]['description']);
        $this->assertSame('41500', $r->amount, 'from «اجمالي الفاتورة», not the largest/first number');
        $this->assertSame('1002', $r->invoiceNumber);
        $this->assertSame('2022-06-08', $r->transactionDate);
        $this->assertSame('مؤسسة الشروق', $r->counterparty);
        $this->assertSame('income', (new TransactionTypeSuggester)->suggest($r->rawText), '«فاتورة مبيعات»');
    }
}
